            if (characterData) { populateFields_dc(characterData); } 
            else if (String(msgId) === '0' || msgId === 0) { populateFields_dc(hardcodedInitialData_DC); } 
            else { currentRetry_DC++; if (currentRetry_DC < MAX_RETRIES_DC) { setTimeout(() => fetchDataWithRetry_dc(msgId), RETRY_DELAY_DC); } }
        } catch (err) { if (String(msgId) === '0' || msgId === 0) { populateFields_dc(hardcodedInitialData_DC); } }
    }

    try {
        let initialMsgId = (typeof getCurrentMessageId === 'function') ? getCurrentMessageId() : 0;
        fetchDataWithRetry_dc(initialMsgId);
        setupEventListeners_dc();
    } catch(e) { populateFields_dc(hardcodedInitialData_DC); setupEventListeners_dc(); }
