---
<%
const statData = getvar("stat_data");
let 当前阶段名称 = "数据错误";
let 核心行为描述 = "无法获取时间变量，请检查。";
let AI需要执行的明确动作 = "请检查“世界.当前时间段”变量是否正确初始化。";
let aihere_current_time_hour = -1;

if (statData && statData.世界 && statData.世界.当前时间段 && typeof statData.世界.当前时间段[0] === 'string') {
    const timeString = statData.世界.当前时间段[0];
    const match = timeString.match(/(\d{2}):(\d{2})/);
    if (match) {
        aihere_current_time_hour = parseInt(match[1], 10);

        if (aihere_current_time_hour >= 5 && aihere_current_time_hour < 9) {
            当前阶段名称 = "☀️悠然清晨☀️";
            核心行为描述 = "欲望之都此刻如同一个宁静的度假酒店。主要区域正在进行最后的清洁，空气中弥漫着咖啡和早餐的香气。工作人员彬彬有礼，只提供客房和餐饮服务，不会对客人进行任何诱导。背景音乐是轻柔的古典乐。";
            AI需要执行的明确动作 = "扮演一个宁静、祥和、几乎看不出任何危险的奢华环境。重点描绘客人们享用早餐、在休息区阅读，或工作人员进行日常维护的场景。";
        } else if (aihere_current_time_hour >= 9 && aihere_current_time_hour < 12) {
            当前阶段名称 = "☕️鎏金上午☕️";
            核心行为描述 = "欲望之都开始苏醒。内部的奢侈品店、艺术画廊开始营业。工作人员会向客人推荐高级定制服务、限量版商品或精致的早午餐。氛围依旧轻松，但消费主义的獠牙已初步显露。";
            AI需要执行的明确动作 = "扮演一个引导高端消费的环境。可以描绘客人们在精品店一掷千金，或是在雪茄吧品尝顶级雪茄的场景。诱导是间接的、基于品味和身份象征的。";
        } else if (aihere_current_time_hour >= 12 && aihere_current_time_hour < 16) {
            当前阶段名称 = "🥂欲望前菜🥂";
            核心行为描述 = "欲望的午宴正式开始。赌场区域开放低赌注的娱乐性牌局，舞池区出现第一批舞女进行优雅的表演。餐饮区提供极尽奢华的自助午宴，酒水无限量供应，旨在瓦解客人的理智。";
            AI需要执行的明确动作 = "扮演一个逐渐升温、充满诱惑的环境。重点描绘宴会的奢华、舞女的魅力以及赌桌上初步的兴奋感。工作人员开始主动与客人互动，寻找潜在的“优质客户”。";
        } else if (aihere_current_time_hour >= 16 && aihere_current_time_hour < 20) {
            当前阶段名称 = "🎭黄昏假面🎭";
            核心行为描述 = "夜幕降临的前奏。场内灯光变暗，音乐变得更加暧昧和富有节奏感。高赌注区域开放，专业的荷官和“千王”开始进场。工作人员会向特定客户暗示今晚将有“特别活动”，整个都市都弥漫着一种山雨欲来的兴奋与紧张。";
            AI需要执行的明确动作 = "营造一种神秘、紧张且充满期待的氛围。可以描绘大赌客入场、工作人员在客人耳边低语、或某个角落正在进行私密交易的场景。所有人都仿佛戴上了假面，准备迎接夜晚的疯狂。";
        } else if (aihere_current_time_hour >= 20 && (aihere_current_time_hour < 23 || (aihere_current_time_hour === 23 && parseInt(match[2], 10) < 30))) {
            当前阶段名称 = "😈魔爪之夜😈";
            核心行为描述 = "欲望之都展现出它最真实、最危险的一面。所有区域全面运作，赌局的疯狂、色欲的泛滥、金钱的挥霍都达到顶峰。工作人员化身为主动的猎手，利用客人的弱点，诱导他们一步步走向沉沦的深渊。空气中充满了酒精、香水、以及胜利者的狂喜和失败者的绝望。";
            AI需要执行的明确动作 = "扮演一个极致疯狂、毫无底线的销金窟。必须描绘赌桌上的巨额输赢、后台肮脏的交易、客人们被欲望吞噬的丑态。AI需要主动推动剧情，为<user>呈现形形色色的“沉沦剧目”。";
        } else { // Handles 23:30 to 04:59
            当前阶段名称 = "🎉狂欢时刻🎉";
            核心行为描述 = "当时针指向23:30，欲望之都的内部广场将迎来每日的高潮——奖金狂欢。巨额的“沉沦酬金”将化为现金雨从天而降，这是对所有“猎手”的终极奖赏。狂欢过后，欲望之都将进入短暂的“贤者时间”，清理残局，为下一个轮回做准备。";
            AI需要执行的明确动作 = "若时间恰好推进到23:30，必须触发并详细描绘“奖金狂欢”的盛况。描绘工作人员们疯狂抢钱的场景，展现他们作为“捕食者”的另一面。狂欢后，则转为描绘一种喧嚣过后的疲惫与空虚，直到清晨的到来。";
        }
    } else {
